INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pokka-man', 93777, '2018-04-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob0mu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mmfduy4hkh6ij7xatulu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokka Man', 'Pokka Man is a kidfriendly game for everybody. But a real challenge for the Retro classic gamers. Pokka Man Arcade is fun, challening and a difficult platform survival game. You begin at the top and you have to go down as far as possible through the dangerous obstacles. Reach the highest level with your skills. This game has an auto checkpoint system. Each color rainbow scarf you obtained wil add 1+ to your total level score. Move Pokka Man by simply pressing the left, up and right arrow key on your keyboard. Pokka Man is now only available for windows. In the future Pokka Man will also be available for Linux and Mac OS X. So stay tuned for more upcoming updates about Pokka Man!!!Pokka Man includes 3 Modes: Easy Mode Normal Mode Hard ModeGame Update''s (Bug fix list) Checkpoint system works now correct Fire Animation added No more double music background in the main menu Spinning obstacles collision detection works now correct' FROM games WHERE igdb_id = 93777 ON CONFLICT (game_id, language_code) DO NOTHING;
