INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stonewall Penitentiary', 'Stonewall Penitentiary is an indie murder mystery adventure that is presented in the visual style of graphic novels. It pays tribute to Agatha Christie''s classic And Then There Were None and horror thrillers like Scream and Saw. Discover why you and six others were kidnapped by an unknown captor as you search an eerie prison and solve mind-bending puzzles to determine "whodunit!"
