INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dash Island', 'Dash Island has been evacuated! You will be sent down to Dash Island with the sole purpose of liberating the Island and returning peace to the citizens. Your character must make their way through a maze with the objective of reaching the end, while avoiding enemies. The level will reset if the enemies catch you! Some levels will be timed and some will require you to activate switches throughout the maze.INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 109837 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
