INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drizzlepath: Deja Vu', 'A man embarks on a journey toward the top of a mountain, to discover the truth of his existence. Along the way, he ponders the nature of life itself. Drizzlepath: Deja Vu is a spiritual revisitation of Tonguç Bodur''s very first game, Drizzlepath.' FROM games WHERE igdb_id = 101399 ON CONFLICT (game_id, language_code) DO NOTHING;
