INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blind Boris', 'Blind Boris is a survival horror about a blind person. The character arrives to the hospice and a week later strange things begin to happen in him. Staff disappears, terrible sounds are heard outside, exit doors are tightly locked, and aggressive visitors enter the building.' FROM games WHERE igdb_id = 84061 ON CONFLICT (game_id, language_code) DO NOTHING;
