INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('30-years-of-nintendont', 215379, '2018-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co55zh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scilf6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '30 Years of Nintendon''t', 'In 1988, SEGA released the Megadrive home console in Japan. In 1989, the machine was released in the USA under the name Sega Genesis. To convince players that the 16-bit Megadrive / Genesis was better than the then-ageing Nintendo NES console, Sega created ads with a brilliant headline: "Genesis does what Nintendon''t". "30 Years of Nintendon''t" is a tribute to the Megadrive / Genesis console and this wonderful marketing campaign.
