INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vigilantes', 'Inspired by the classic turn based strategies of the 90''s, Vigilantes is a compelling, crime themed, turn based tactical RPG with an old school heart. Become Sam Contino, an idealist dragged down the rabbit hole of vigilantism and embark on a personal crusade against crime in Reiker City.' FROM games WHERE igdb_id = 25597 ON CONFLICT (game_id, language_code) DO NOTHING;
