INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Masters of Anima', 'Go to the aid of your future bride, using the powers of Anima to summon an army of magical Guardians in your quest to defeat Zahr''s dreaded Golems. Learn to control new types of Guardians on your adventure, each with their own unique talents and abilities useful to explore the vast world of Spark and reveal its secrets, as well as to take down the formidable bosses that stand in your way. As your victories rack up, acquire new powers and abilities for both yourself and your Guardians to become a true Master of Anima.' FROM games WHERE igdb_id = 28286 ON CONFLICT (game_id, language_code) DO NOTHING;
