INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Midnight Sanctuary', 'The Midnight Sanctuary blurs the line between reality and surreal both in storytelling and visual style. Blending static 2D textures and moving 3D models creates a striking visual effect, further enhanced in VR. The Midnight Sanctuary''s graphics, which incorporate a stained glass-style to create a beautiful aesthetic, provides an eerie background for the alarming events Tachibana encounters.' FROM games WHERE igdb_id = 36759 ON CONFLICT (game_id, language_code) DO NOTHING;
