INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('more-lies', 322084, '2018-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91du.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scun7p.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'More Lies', 'Heavily inspired by Yume Nikki and Don''t Hug Me I''m Scared, the content in M o RE Lie s centers specifically around playing as an antisocial adolescent who calls himself Henry, as he traverses the many diverse worlds that are laid out before him. His main objective, however, is to search for the four "Lies"; simply put, four people (including Henry himself) who have an apparent significance which cannot be explained by traditional methods. These important figures are hidden amongst the many various locales, and it is your job, as the player, to of course encounter them and add such beings to your roster. Along the way you, the player, may find yourself learning a little about your own existence, as well as discovering the "true meaning of the universe". And we are afraid this is the only way of going about doing so. Nonetheless, we have decided to let the opportunity to be yours, that is, if you have the desire to help such a story transpire. You have the ability to make that decision now...' FROM games WHERE igdb_id = 322084 ON CONFLICT (game_id, language_code) DO NOTHING;
