INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dot to Dot Puzzles', 'Dot To Dot Puzzles for Adults is an amusing and relaxing game for young and mature people with an amazing world of complex drawings and diverse themes. Discover what is hidden behind, connecting dots orderly. Once puzzle is solved, pictures can be customized, changing lines colors. Images to draw by connecting the dots are classified into tags as Art, Monuments, Landscapes, Mandalas, Animals, Vehicles and Sports among others.' FROM games WHERE igdb_id = 104897 ON CONFLICT (game_id, language_code) DO NOTHING;
