INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armored Brigade', 'Armored Brigade is a real-time tactical wargame, focusing on realism and playability. The game has drawn inspiration from classics such as Close Combat, Steel Panthers and Flashpoint Campaigns: Red Storm. In Armored Brigade the Cold War has turned hot, and Europe is once again torn apart by conflict. An "Iron Curtain" divides the Western Powers gathered together under the NATO banner from the Soviet Union and its Warsaw Pact Allies.' FROM games WHERE igdb_id = 109035 ON CONFLICT (game_id, language_code) DO NOTHING;
