INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fitness Boxing', 'Get off the couch and get moving with fun, boxing-based rhythmic exercises set to the instrumental beats of songs by popular artists, including Lady Gaga, Pitbull and Kesha. You can personalize your workouts by selecting from different fitness goals. Train your way, whether you''re on your own, with a friend, at home, or on the go! Now you can work out anytime, anywhere on the Nintendo Switch system!' FROM games WHERE igdb_id = 103371 ON CONFLICT (game_id, language_code) DO NOTHING;
