INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mulaka', 'Dive into northern Mexico''s breathtaking landscapes with Mulaka, a 3D action-adventure game based on the rich indigenous culture of the Tarahumara. Renowned for their impressive running abilities, embark on the journey of a Sukurúame - a Tarahumara shaman - as you fight back the foulness corrupting the land, while drawing upon the powers of demigods. From solving puzzles in environments inspired by real Sierra Tarahumara locations, to heated hand-to-hand combat with creatures pulled from the region’s mythology, find out why the Tarahumara have earned a reputation for being superhumans.' FROM games WHERE igdb_id = 28692 ON CONFLICT (game_id, language_code) DO NOTHING;
