INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unmoor', 'Louisa has spent all her life in the sea with her father sailing on board of a ship called "Diossa" and she had no intention to change it. But, as soon as she returned frome the Maritime Acadimy , she learnt that her father had been deceived by a monsieur Viardo who had taken their ship in his possession.' FROM games WHERE igdb_id = 89341 ON CONFLICT (game_id, language_code) DO NOTHING;
