INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battlesky-vr', 76841, '2018-01-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co23ws.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gxz2dnpwrwr5wib1e5qh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BattleSky VR', 'BattleSky VR is a Multiplayer VR game at its core, bringing MOBA style gameplay to the VR platform. Each player picks a Hero with vastly different size, powers and gameplay style to engage in fast-paced aerial combats against other players. Play online against other players with classic Team Deathmatch, Capture The Flag, and other teamplay modes of up to 4v4 players! Each Hero has a single player and co-op mission mode where you''ll learn the back story about the Heroes, and get familiar with the controls and the unique Flying Locomotion mechanism.' FROM games WHERE igdb_id = 76841 ON CONFLICT (game_id, language_code) DO NOTHING;
