INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Three Kingdoms: Ancient Battlefield', 'Three Kingdoms: Ancient Battlefield is an independent game created by me. It is a 20-30 minute strategy game of battle situation. Players can lead their three Kingdoms generals into battlefield to fight. In the game, they also need to occupy the city pool, layout economy, dispatch troops and generals to attack and fight, as well as in fog...' FROM games WHERE igdb_id = 113172 ON CONFLICT (game_id, language_code) DO NOTHING;
