INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teen Titans Go! Figure', 'Teen Titans GO! Figure is a three-on-three-based combat game. You will face off against the bad guys with your team of heroes, progressing through the story of the game in a bid to solve a mystery and save the Teen Titans. You can customise your team both cosmetically and by levelling them up to make them more powerful. The game features a full story mode which you can play through as any of the Teen Titans. You can explore Gotham City and Metropolis as well as the Teen Titans home of Jump City.' FROM games WHERE igdb_id = 105464 ON CONFLICT (game_id, language_code) DO NOTHING;
