INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quickshot', 'The makers of The Tower send you to the Quickshot boot camp to give you a fighting chance in the war against the machines. Use pistols, shotguns, lasers, submachine guns and chain guns to take down targets launched at you and avoid obstacles to not get smashed. Open fire in slow motion and get in cover when getting shot at or wield a weapon from more civilized days.' FROM games WHERE igdb_id = 89593 ON CONFLICT (game_id, language_code) DO NOTHING;
