INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tie-a-game-about-depression--1', 326716, '2018-07-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co974e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwjpd.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TIE: A game about depression', 'TIE is a game about depression and the daily grind we are all forced too endure. Experience a week of more of the same, every day, through the eyes of our main character as the world and its inhabitants slowly start too become increasingly unfamiliar. Irregularities in the world and from deep within plague your day to day and a strange force seems to tear the very fabric of reality itself, as it becomes apparent that not all is as it seems in this short, atmospheric game about depression and existential dread.
