INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic.Exe: The Spirits of Hell', 'One late night, Sonic the Hedgehog is running through Green Hill Zone as Tails communicates with him via radio. Sonic notes that the entire zone seems empty but is intrigued by something: a strange black and red object in one of the palm trees. Tails warns Sonic to be careful, with the hedgehog brushing the warning off, but shortly after the radio cuts off. Tails panics and decides to investigate to see if Sonic is OK.' FROM games WHERE igdb_id = 255852 ON CONFLICT (game_id, language_code) DO NOTHING;
