INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Server Tycoon', 'Server Tycoon is a strategic and management (MMORTS) video game where players strive earning game coins offering internet services to their customers. The simulated companies can be listed on a Stock Exchange and players can buy shares from allies or opponents receiving profits, but remember pirates and competitors will try to stop you with frequent cyber attacks so, improve your infrastructure, organise your defences and try to climb the top of the hi-tech finance!' FROM games WHERE igdb_id = 16125 ON CONFLICT (game_id, language_code) DO NOTHING;
