INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hentai Unlimited', 'Dive into the world of Hentai Unlimited, a captivating and relaxing puzzle game where your goal is deceptively simple: rotate pieces to reveal tantalizing, lewd artwork. But beware, it''s more addictive than you might think! Each picture is randomly selected, pulled fresh from the web for an infinite supply of hentai puzzles.' FROM games WHERE igdb_id = 367510 ON CONFLICT (game_id, language_code) DO NOTHING;
