INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Horde: Zombie Outbreak', 'Ever wanted to control a bloodthirsty horde of zombies and wreak havoc on cities around the world? Well now you can! In Horde: Zombie Outbreak the player assumes the role of the zombies and must overthrow the world by infecting the humans! Each person you infect will become part of your horde. As your horde grows stronger so to does the human resistance, the player must use abilities that are linked to certain zombie types to help them fight through the police, swat and army!' FROM games WHERE igdb_id = 105576 ON CONFLICT (game_id, language_code) DO NOTHING;
