INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Russian Subway Dogs', 'Welcome, comrades! Meet Russian Subway Dogs! We have done extensive, totally legal research in order to fine tune this chaotic simulation for what it''s like to scavenge for food from Russian commuters. Surviving isn''t easy when you are dodging volatile vodka, rival dogs, and the rare and dangerous Subway Bear!' FROM games WHERE igdb_id = 56564 ON CONFLICT (game_id, language_code) DO NOTHING;
