INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heartbreak High: A Break-Up Simulator', 'Imagine you''re the most popular kid in school. So popular, in fact, that you''re dating every single person in your class. The only problem? You''ve decided to break up with all of them, one by one. An arcade-style spin on dating simulators that asks you to break up with all of your high school sweethearts.' FROM games WHERE igdb_id = 101256 ON CONFLICT (game_id, language_code) DO NOTHING;
