INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ongeki', 'Ongeki is a Japan-exclusive arcade rhythm game by Sega, released in 2018. It combines traditional rhythm gameplay with bullet-hell elements, using a joystick and six-button layout. Players hit notes, dodge obstacles, and attack enemies in time with music. It features a gacha-style card system for upgrading characters and uses a unique GP (Game Points) credit system. The game is part of Sega''s rhythm game lineup alongside maimai and Chunithm.' FROM games WHERE igdb_id = 122479 ON CONFLICT (game_id, language_code) DO NOTHING;
