INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grim Tales: The Hunger - Collector''s Edition', 'Your niece Jackie Gray has been murdered by a killer whose crimes went unsolved 17 years ago. Team up with Jackie''s policeman father and use your powers to go back in time and stop the killer before their murder spree claims Jackie''s life in the present! Will you be able to solve the cold case, or will the killer rise again to begin another reign of terror? Travel into the past to find all the clues – and the villain!' FROM games WHERE igdb_id = 250596 ON CONFLICT (game_id, language_code) DO NOTHING;
