INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Memoirs of Murder: Welcome to Hidden Pines', 'It''s time to relocate to the town of Hidden Pines! Your excitement over escaping the big city and enjoying your new home quickly turns tragic when your neighbor is murdered! To make matters worse, your spouse is the prime suspect! It''s up to you to piece together the evidence and clear their name. This small-town is hiding some big secrets. Can you crack the case in time? Find out in this gripping Hidden-Object Puzzle adventure!' FROM games WHERE igdb_id = 322578 ON CONFLICT (game_id, language_code) DO NOTHING;
