INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'How long can human beings exist', 'How long can human beings live on Earth? Will the human being be destroyed when disaster strikes? A game from the future. Challenge more than 50 kinds of disasters that will destroy humanity in the future. Victims or survivors, destroy the world or save humanity? Human civilization is about to usher in the end, you are entrusted with a heavy responsibility, to the future, to lead all humanity to fight against disasters, to strive to survive for a long time before the end of the day, to continue the civilization of human prosperity!' FROM games WHERE igdb_id = 109657 ON CONFLICT (game_id, language_code) DO NOTHING;
