INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gral', 'GRAL is a futuristic racing game with combat elements, a tribute to the 90s games such as Megarace, POD, DethKarz. Rides on solid speeds that spin 500Kmh on articulated tracks with shortcuts, jumps, parabolic and death rides! 5 stables with unique features coming from 5 planets whose predominant element also affects attack and defense weapons. Possibility to blend power-ups together to create a new one in real time that is the result of the mix of the two originals. Multiplayer and SplitScreen modes captivating through the ability to share power-ups with challenging team-mates for challenging team strategies!' FROM games WHERE igdb_id = 101295 ON CONFLICT (game_id, language_code) DO NOTHING;
