INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beer Pong VR', 'Beer Pong VR brings the classic party game into the VR world of competitive gaming. With multiple immersive environments to play in, don''t be surprised if you try interacting with the scenery. No more chasing pong balls and no more spilling your precious beer with this fast-paced arcade-style game. Polish your skills at the pong table for hours on end and get ready to challenge your friends in the upcoming Online Multiplayer update.' FROM games WHERE igdb_id = 88194 ON CONFLICT (game_id, language_code) DO NOTHING;
