INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris Effect', 'Named after a real-world phenomenon where players'' brains are so engrossed that images of the iconic falling Tetrimino blocks linger in their vision, thoughts, and even dreams, Tetris Effect amplifies this magical feeling of total immersion by surrounding you with fantastic, fully three-dimensional worlds that react and evolve based on how you play. Music, backgrounds, sounds, special effects - everything, down to the Tetris pieces themselves, pulse, dance, shimmer, and explode in perfect sync with how you''re playing.' FROM games WHERE igdb_id = 103221 ON CONFLICT (game_id, language_code) DO NOTHING;
