INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Life', 'College, a fun time for some, a bad time for others. All have hopes and dreams, but some demons pull them down to a hole they can''t climb out of. Life changes based on the smallest things, and those who suffer can sometimes see a light to help escape the darkness, or be forever wrapped in it.' FROM games WHERE igdb_id = 90406 ON CONFLICT (game_id, language_code) DO NOTHING;
