INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Line Slider', 'Paint and slide your way around in this exciting side-scroller as Bip, a mischievous vandal intent on mayhem! Paint and draw your way through foreign lands where the villagers can’t stand you and the bigger the mess you can make, the better! Cruise through rolling green hillsides and quaint villages, but be sure to escape the grasp of the angry villagers! Forget about being a hero, bad guys have all the fun! How many villages can you leave you vandalize before you get caught?' FROM games WHERE igdb_id = 388455 ON CONFLICT (game_id, language_code) DO NOTHING;
