INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Tower Tiny Square', 'Dodge bullets, leap lava pits, and wall-jump your way up the Big Tower in this precision platformer. The controls are simple and the obstacles are fair. But do you have the skill necessary to make it to the top? No sprint, no double-jump, and no floaty controls! Just quick deaths and generous respawn points.' FROM games WHERE igdb_id = 76318 ON CONFLICT (game_id, language_code) DO NOTHING;
