INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Godly Corp', 'Godly Corp is an over-the-top simulator where you play as intern god in a corporation. Use your tentacle arm to perform many unusual office tasks. Master woobly tentacle physics and try to not destroy all life on the planets that you take care of. Every day brings completely new challenges. Expect everything including chainsaw robots, bug infestation, space trips and more.' FROM games WHERE igdb_id = 88122 ON CONFLICT (game_id, language_code) DO NOTHING;
