INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All Walls Must Fall', 'All Walls Must Fall is a tech-noir spy thriller set in a Berlin of 2089 where the Cold War never ended. A game in the isometric action tactics genre, you command secret agents using time travel, social stealth and combat. Prevent nuclear annihilation. Bring down the Wall. Love, kill, and remix reality to explore the meaning of freedom in a parable reflecting upon current global issues in the mirror of a fantastic future past.' FROM games WHERE igdb_id = 27793 ON CONFLICT (game_id, language_code) DO NOTHING;
