INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tempest Citadel', 'Assume the role of an enigmatic Captain from Terra as he embarks on a mission to explore a deadly world that promises wondrous and terrible power. Tempest Citadel is a strategy game set on a storm-ruled planet. Build a mighty Citadel in the clouds and lead your crew into battle.' FROM games WHERE igdb_id = 75106 ON CONFLICT (game_id, language_code) DO NOTHING;
