INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sand-is-the-soul', 75610, '2018-04-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co272n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/h4rmi0toqjflqmfpwsaz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sand is the Soul', 'Sand ​ ​is​ ​the ​ ​Soul ​ ​is​ ​a ​ ​unique ​ ​combination ​ ​of ​ ​side ​ ​scrolling ​ ​beatemup ​ ​and ​ ​action ​ ​RPG. ​ ​It ​ ​is​ ​a hard, ​ ​unforgiving ​ ​and ​ ​demanding ​ ​game ​ ​set ​ ​in ​ ​a ​ ​original ​ ​post ​ ​punk​ ​Victorian ​ ​esque ​ ​lore. ​ ​With a ​ ​distinct ​ ​original ​ ​graphical ​ ​style, ​ ​unique ​ ​multiple ​ ​moral ​ ​systems​ ​including ​ ​karma, ​ ​crime, sanity, ​ ​an ​ ​engaging ​ ​original ​ ​Soundtrack... ​ ​Sand ​ ​is​ ​the ​ ​Soul ​ ​is​ ​a ​ ​modern ​ ​day​ ​itteration ​ ​and love ​ ​letter​ ​to ​ ​an ​ ​old ​ ​school, ​ ​niche ​ ​genre ​ ​where ​ ​the ​ ​game ​ ​let’s​ ​you ​ ​do ​ ​what ​ ​you ​ ​want ​ ​and doesn’t ​ ​spoonfeed ​ ​or​ ​think​ ​for​ ​you.' FROM games WHERE igdb_id = 75610 ON CONFLICT (game_id, language_code) DO NOTHING;
