INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Settlers III: History Edition', 'The Settlers III is a lavishly designed, strategy-filled fantasy civilization simulation in which you have your industrious little subjects construct buildings, produce goods, and conquer new lands in exciting real-time battles. Includes The Settlers III, The Settlers III Mission CD, and the expansion pack Quest of the Amazons. Some of the improvement highlights include: Windows 10 compatibility, auto saving, 4K and dual monitor support, and multiplayer via Uplay.' FROM games WHERE igdb_id = 117188 ON CONFLICT (game_id, language_code) DO NOTHING;
