INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic SMS Remake', 'A fanmade remake of Sonic the Hedgehog 1 for Sega Master System, featuring new characters and habilities, new zones and levels, a time attack mode, a local wi-fi/lan multiplayer mode, a boss rush, Super transformations, internal memory card saving, 5 different endings, Big Rings to get the 7 chaos emeralds, a pause menu, a debug mode and cheats, new color palettes, gamepad support, 30 and 60 fps support, 4:3, widescreen and ultrawide.' FROM games WHERE igdb_id = 227798 ON CONFLICT (game_id, language_code) DO NOTHING;
