INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The 25th Ward: The Silver Case - Digital Limited Edition', 'It is five years since the events of 1999’s “The Silver Case,” set in the new 25th Ward that arose in the bayside area of Kanto. In a room of the “Bayside Tower Land” apartment complex, a woman is found murdered under mysterious circumstances. This sets off a series of seemingly random events throwing together multiple protagonists including The Silver Case’s Tokio Morishima. With all viewpoints assembled, a truly shocking pattern emerges…' FROM games WHERE igdb_id = 124886 ON CONFLICT (game_id, language_code) DO NOTHING;
