INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Professor Layton and the Curious Village HD for Mobile', 'The original Professor Layton adventure remastered for Android and iOS. Featuring a distinctive artistic style that oozes old-world charm, the game’s quirky cast of characters instantly comes to life. The animated cutscenes, remastered in HD, tell key parts of the tale in gorgeous detail. And ever-present in the background, the original soundtrack, beloved by many players, keenly captures the mood of the Layton universe.' FROM games WHERE igdb_id = 102865 ON CONFLICT (game_id, language_code) DO NOTHING;
