INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Micro Pico Racers', 'Micro Pico Racers is a fun top-down arcade racing game with a retro style graphics where you control of little cars racing over exciting tracks. Start your engines and prepare for the craziest and most addictive racing game ever. Fast-paced racing game with a fresh interpretation of the 16-bit style. This is an arcade racing game based on games that I loved playing in the arcades growing up. You could say it''s inspired by those games, maybe a tribute to them or simply a rip off, any of these could be true!' FROM games WHERE igdb_id = 96665 ON CONFLICT (game_id, language_code) DO NOTHING;
