INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cave Brawlers', 'Cave Brawlers is a 2D hack ''n slash which takes inspiration from games like Castle Crashers, Wonder Boy in Monster Land, and Shovel Knight. The game requires the player to use different moves and combinations to take down enemies and succeed. The game is heavily story based and will take you on an adventure through the life of a soldier of a medieval village turned hero due to an attack.' FROM games WHERE igdb_id = 82034 ON CONFLICT (game_id, language_code) DO NOTHING;
