INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dig Dog', '"Dig Dog is an action roguelike platformer. Dig to discover treasure, adventure and bones! Jump, dash, stomp and dig your way through a strange world inhabited by stranger creatures. Dig Dog combines classic platforming action with endless, generated levels to explore...and dig! Includes two modes of play: Bone Hunt, the roguelike treasure hunt. Dig for bones across four worlds of increasing difficulty. Die a lot. Free Dig, an endless digging experience. Dig through an infinite set of levels with minor challenge and no game overs."' FROM games WHERE igdb_id = 87678 ON CONFLICT (game_id, language_code) DO NOTHING;
