INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle Monarch: Egypt', 'An ancient tomb has been uncovered and it''s filled with hidden treasures. Solve 15 sets of ancient puzzles and unlock your way to the bottom of the tomb. Each set contains a three by three and six by six puzzle. To move on to the next level you will have to solve both puzzles and journey deeper into the tomb.' FROM games WHERE igdb_id = 109335 ON CONFLICT (game_id, language_code) DO NOTHING;
