INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RoboHeist VR', 'RoboHeist is an intensive and immersive Virtual Reality stealth game specially designed for HTC Vive VR device. Your mission is to find and power up the teleport on each level. Watch out for evil robots, lasers and alarms. Hide in closets and chests, climb ladders, crawl and crouch. Sneak around in shadows and use weapons to destroy the robots.' FROM games WHERE igdb_id = 86561 ON CONFLICT (game_id, language_code) DO NOTHING;
