INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yuè Lán Chuánqí 2: Zhòu Yìn Zú Chuánshuō', 'Set ten years after the first game, you play as Lu Xiaofei — a boy bearing a mysterious mark — who gets swept into a cross-realm adventure after his adoptive parents go missing. Along the way he crosses paths with the feared Cursed Seal Tribe, and three girls who each leave a lasting impression on him. A short but emotionally weighty RPG Maker freeware game from Taiwan with a devoted cult following.' FROM games WHERE igdb_id = 394177 ON CONFLICT (game_id, language_code) DO NOTHING;
