INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Swords of Ditto', '"The Swords of Ditto is a compact action RPG that creates a unique adventure for each new hero of legend in the relentless fight against the evil Mormo. Explore a delightful but dangerous overworld, brave menacing dungeons, and improve your hero in a charming village, during your quest to overcome the evil that plagues the island. Unleash the mystical Sword of Ditto and grab a co-op friend for an unforgettable adventure filled with delightful characters, extraordinary loot, and heroic battles!"' FROM games WHERE igdb_id = 36798 ON CONFLICT (game_id, language_code) DO NOTHING;
