INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Germination', 'An astronaut has crash-landed on an alien planet, and it''s started to rain... seeds. Featuring a campaign and an endless mode with leaderboards, Germination is an arcade platform-em-up about stomping your way to the highest combo, excruciatingly detailed with hand-crafted animations.' FROM games WHERE igdb_id = 95328 ON CONFLICT (game_id, language_code) DO NOTHING;
