INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Foreveracers', 'The bouncy wobbly arcade online multiplayer driving game. Jump in to the action with no fuss. Race, roam, roll, crash, and challenge as you drive around the game world day and night. Cut corners, find shortcuts and avoid other players while trying to set the best lap times or win the challenges.' FROM games WHERE igdb_id = 91328 ON CONFLICT (game_id, language_code) DO NOTHING;
