INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-wayhaven-chronicles-book-one', 88043, '2018-03-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25v6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arfq1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Wayhaven Chronicles: Book One', 'Play as a detective on your first case in the small town of Wayhaven, opening your eyes to a world bigger than you thought. Totalling 440,000 words, this supernatural romance interactive novel allows you to pick your gender (female, male, or non-binary) and orientation (straight, gay, or bisexual). Choose which detective skills you will focus on - deduction, combat, science, or people skills. Use multiple dialogue options to express your personality and define your relationships with friends, family, and enemies. Start a romance with one of the vampires of Unit Bravo, to be developed over a 7 part series.' FROM games WHERE igdb_id = 88043 ON CONFLICT (game_id, language_code) DO NOTHING;
