INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Chaos', 'Sonic Chaos is a fan game and re-imagining of the 1993 Sega Game Gear and Master System platform game of the same name. Based on the current style of 2D classic Sonic games inspired by Sonic Mania, Sonic Chaos updates the 8 bit visuals of the original and adapts a play style more closely resembling the classic 16-bit games.' FROM games WHERE igdb_id = 136816 ON CONFLICT (game_id, language_code) DO NOTHING;
