INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Combo Jumper', 'Combo Jumper is a first-person platformer. The core mechanic of the game is combo points. You gain a combo point every time you wall jump and each combo point multiplies how far you jump on the next wall however upon touching the ground your combo points get reset so to make a large jump you have to make consecutive wall jumps to make...' FROM games WHERE igdb_id = 110930 ON CONFLICT (game_id, language_code) DO NOTHING;
