INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flying Fish Quest', 'Dolly, the little fish and Tim, her sea-horse friend live in a beautiful undersea world. Dolly is a flying fish and likes to fly out of the water to enjoy the warmth of the sun. One day, it suddenly grows darker right in the middle of the day! As the darkness sets in, Dolly and Tim become more and more concerned. Help them on their journey to save their beloved lagoon and overcome many puzzles and obstacles along the way!' FROM games WHERE igdb_id = 192313 ON CONFLICT (game_id, language_code) DO NOTHING;
