INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Splash Blast Panic', 'SPLASH BLAST PANIC is a multiplayer competitive party game where you must shoot, ram, dodge and overall bully your opponents outside the screen with a variety of watergun-based weaponry. Inspired by old arcade titles as well as newer competitive party games, ruin all your friendships in a variety of stage which may or may not have various level of gimmicks that could backhand you if you''re not careful, or tell that person you always despised your true feelings with waterbomb launchers, bubble prisons, watergun sentries, reflective shields and more !' FROM games WHERE igdb_id = 31996 ON CONFLICT (game_id, language_code) DO NOTHING;
