INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The 6-Digit Computer', 'The 6-Digit Computer is a programming game in an alternate past. You, Deam Mead, just got hired at Farworks as a programmer for their new operating system, HTaeD / O6. However, it''s not as simple as you might think! The computer operates on bijective senary, which means that it only has the digits 1-6. So 7 becomes 11, 24 becomes 36 and so on.' FROM games WHERE igdb_id = 288924 ON CONFLICT (game_id, language_code) DO NOTHING;
