INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shanky-the-vegans-nightmare', 114906, '2018-06-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5as1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arazn.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shanky: The Vegan''s Nightmare', 'Shanky - is a joyful meat grinder and mince is its movement force. Swallow up everything you can and collect Meat-Cola to stay on the move. Participate in a stunning story of love and self-sacrificing. Depending on the level, Shanky would change its movement force accessories to legs, wheels, wings and boat. During the boss battles, you would learn how to use its mince launcher. Collect Meat-Cola to expand Shanky''s stomach and success is guaranteed. And remember - there is never enough mince, so keep grinding!' FROM games WHERE igdb_id = 114906 ON CONFLICT (game_id, language_code) DO NOTHING;
