INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Heat of Battle', 'In the game you play as Meat McBeef and Bunny Amour. The Heat Of Battle combines the themes of a platform game with a point and click adventure. During the casting for their next game the protagonists get mixed up. This results in the action guy ending up in the dating sim, while the cute rabbit stars in the action shooter game.' FROM games WHERE igdb_id = 106673 ON CONFLICT (game_id, language_code) DO NOTHING;
