INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmos Invictus', 'Choose your faction and embark on an epic fight to determine the fate of humanity in Cosmos Invictus, an interstellar collectible card game. Prepare to engage in intense, strategic battles with Mechs, pilots and unique customizable spaceships. Go head-to-head with other players in the PvP BattleZone arena, face off against the computer in PvC missions, or scout out challenges for profitable rewards. Will your vision for humanity come to light… or disappear into oblivion?' FROM games WHERE igdb_id = 103030 ON CONFLICT (game_id, language_code) DO NOTHING;
