INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farming Simulator 19', 'Farming Simulator 19 takes the biggest step forward yet with the franchise’s most extensive vehicle roster ever! You’ll take control of vehicles and machines faithfully recreated from all the leading brands in the industry, including for the first time John Deere, the largest agriculture machinery company in the world, Case IH, New Holland, Challenger, Fendt, Massey Ferguson, Valtra, Krone, Deutz-Fahr and many more.' FROM games WHERE igdb_id = 87210 ON CONFLICT (game_id, language_code) DO NOTHING;
