INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tempest 4000', 'In Tempest 4000, players are once again in control of the Claw, a powerful spacecraft equipped to destroy deadly creatures and other obstructions with rapid-fire shots on vibrant geometric prisms. With three game modes to choose from and 100 levels to conquer, players must eliminate all enemies as quickly as possible to survive and achieve that coveted spot at the top of the leaderboards.' FROM games WHERE igdb_id = 54565 ON CONFLICT (game_id, language_code) DO NOTHING;
