INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('turnabout-in-payne-and-suffering', 330912, '2018-04-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9dnr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvatd.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turnabout in Payne and Suffering', 'Winston Payne, having ceased to be a prosecutor for unspecified reasons, takes on his first case as a defense attorney, defending his brother Gaspen from accusations of committing the perfectly understandable crime of beating the snot out of Larry Butz. But is that all that''s going on here? Can Winston Payne find (and handle) the truth? And what''s with all the cell phones?' FROM games WHERE igdb_id = 330912 ON CONFLICT (game_id, language_code) DO NOTHING;
