INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Case Files: The Countess - Collector''s Edition', 'Lady Eleanor Codington, prominent friend of the Queen herself, has disappeared while renovating her family’s legendary estate. Explore the crumbling grounds of world-famous children’s author Gloria Codington for clues. A towering black mirror may reveal a secret, but gazing into its depths may bring more than just a few years of bad luck. Can you find Eleanor and escape the manor alive? Find out in this heart-pounding hidden-object puzzle adventure game!' FROM games WHERE igdb_id = 112057 ON CONFLICT (game_id, language_code) DO NOTHING;
