INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ZoomnBoom', 'In ZOOMnBOOM, you zoom and boom. But doom and gloom loom for those who oppose you! ZOOM around two gravity-defying arenas and make your three opponents BOOM into the wall of light that trails behind you! Try to be the last one zooming in split-screen battles with up to four players!' FROM games WHERE igdb_id = 107876 ON CONFLICT (game_id, language_code) DO NOTHING;
