INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fliplomacy', 103399, '2018-03-27', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1alp.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fliplomacy', 'How about a game that combines the simple & easy mechanics of childhood favorite board games such as Checkers, Draughts, Othello, Reversi etc with brain twisting puzzle elements & puts it all in a diplomatic setting? The result is an amazing logical puzzle game which is fun for kids, adults & people of all ages! With 150 levels, ranging from easy to some really hard & difficult challenges, you have to develop an abstract strategy to move your token around the board in order to ‘flip’ all the pieces to your side! The board is your world & there is something wrong with it. Many states have changed sides. But they can swing to any side. As the ace Diplomat, it is your job to restore the order. Every step that you take, can win you some states & turn some against you. Make the right moves & flip everyone to your side. Strategize & chart a path across the board; moving, jumping & flipping states as you attempt to solve the 150 different levels! Go ahead & take up the challenge. Can you collect all three stars on each level?' FROM games WHERE igdb_id = 103399 ON CONFLICT (game_id, language_code) DO NOTHING;
