INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Holiday', '画风清奇的RPG作品，故事讲述的是一个小学3年僧，随父母回老家的5天假期生活。在老家的小区你会遇到一群性格各异的小盆宇，展开一张并不是很激烈的假期冒险。' FROM games WHERE igdb_id = 107967 ON CONFLICT (game_id, language_code) DO NOTHING;
