INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('operation-lone-wolf', 107834, '2018-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27nk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arpz6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Operation Lone Wolf', 'Operation Lone Wolf is a multiplayer & soon to be Singleplayer first person shooter, set in the second world war. You can play with up to 10 players, in different free for all gamemodes. At the moment this game has 8 gamemodes, including: standard free for all, gungame, sniper, shotgun and pistol-only and more. You can play on 10 different maps, set on all kinds of locations. Operation Lone Wolf has small maps, and big, more open maps so there are many gameplay options available for the players. This game is not trying to be a realistic representation of WW2, but more of an arcade, fast paced shooter, in which having fun is the main goal. Post launch updates like new maps, new gamemodes etc. will all be free, and there are no in-game purchases in Operation Lone Wolf. The game will cost around $17 at launch.' FROM games WHERE igdb_id = 107834 ON CONFLICT (game_id, language_code) DO NOTHING;
