INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trireme Commander', 'Greek and Persian trireme simulator, from maneuvering a single trireme through to the Battle of Salamis (480BC). The simulation accurately recreates the performance of ancient triremes, and gives the player 16 scenarios to work through. Pass all the scenarios at one level to get promotion to the next, and learn a lot about ancient ships, tactics and battles along the way!' FROM games WHERE igdb_id = 81738 ON CONFLICT (game_id, language_code) DO NOTHING;
