INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stickman-soccer-2018', 95061, '2018-05-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9q7x.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stickman Soccer 2018', 'Stickman Soccer 2018 is the better than ever sequel to the award winning Stickman Soccer with more than 75 million players. Experience pure soccer fun with fast paced arcade gameplay, an astonishing atmosphere, stunning smooth animations, simple controls, insane action and tons of replay value in this from the ground up redesigned Soccer game. Choose your favorite soccer teams and rank up while playing various seasons, national leagues, cups or the World Cup 2018 in Russia as well as online battles with other players all around the world. Stickman Soccer 2018 has tons of new gameplay features like yellow/red cards, sprint button, slow motion replays, overhead kicks, free kicks, … an outstanding stadium and finally the ability to customize all teams, every soccer player and upgrade your team within the transfer market. Choose your favorite soccer team from more than 150 different skilled teams and lead them to glory!' FROM games WHERE igdb_id = 95061 ON CONFLICT (game_id, language_code) DO NOTHING;
